import Foundation

/// Названия городов, которые обслуживают аэропорты: IATA → город.
///
/// Сгенерировано из Wikidata: берётся свойство P931 («обслуживает»), а если городов
/// несколько — побеждает самый населённый (P1082). Так для KGD это Калининград, а не
/// Балтийск, а для HAN — Ханой, а не район Сокшон, который отдаёт adsbdb.
/// Данные лежат строками, чтобы компилятор не разбирал словарь из тысяч элементов.
enum AirportNames {
    static let ru: [String: String] = parse(rawRu)
    static let en: [String: String] = parse(rawEn)

    static func city(iata: String?, russian: Bool) -> String? {
        guard let iata = iata?.uppercased() else { return nil }
        let table = russian ? ru : en
        guard let value = table[iata], !value.isEmpty else { return nil }
        return value
    }

    private static func parse(_ raw: String) -> [String: String] {
        var map: [String: String] = [:]
        map.reserveCapacity(4096)
        for line in raw.split(separator: "\n") {
            guard let separator = line.firstIndex(of: "=") else { continue }
            map[String(line[line.startIndex..<separator])] = String(line[line.index(after: separator)...])
        }
        return map
    }

